use codeint_model::language::SourceSet;
use codeint_model::{has_any_ascii_marker, has_folder_named};

#[cfg(test)]
mod tests;

const GENERATED_SUFFIXES: [&str; 8] = [
    ".g.dart",
    ".freezed.dart",
    ".gr.dart",
    ".mocks.dart",
    ".pb.dart",
    ".pbenum.dart",
    ".pbjson.dart",
    ".pbserver.dart",
];

const GENERATED_MARKERS: [&str; 6] = [
    "generated code",
    "@generated",
    "do not edit",
    "do not modify by hand",
    "auto-generated",
    "autogenerated",
];

const TEST_FOLDERS: [&str; 3] = ["test", "tests", "integration_test"];

pub(crate) fn classify(path: &str, header_comments: &str) -> SourceSet {
    if is_generated(path, header_comments) {
        return SourceSet::Generated;
    }
    if is_test_path(path) {
        return SourceSet::Test;
    }
    SourceSet::Production
}

pub(crate) fn is_tooling_file(path: &str) -> bool {
    let Some((dir, _)) = path.rsplit_once('/') else {
        return false;
    };
    for segment in dir.split('/') {
        if segment.eq_ignore_ascii_case("lib") {
            return false;
        }
        if segment.eq_ignore_ascii_case("tool") || segment.eq_ignore_ascii_case("example") {
            return true;
        }
    }
    false
}

fn is_generated(path: &str, header_comments: &str) -> bool {
    GENERATED_SUFFIXES
        .iter()
        .any(|suffix| path.ends_with(suffix))
        || has_any_ascii_marker(header_comments, &GENERATED_MARKERS)
}

fn is_test_path(path: &str) -> bool {
    path.ends_with("_test.dart") || has_folder_named(path, &TEST_FOLDERS)
}
